<?php namespace App\Actions\Procurement; use App\Models\{GoodsReceipt,StockMovement}; use App\Services\StockService; use Illuminate\Support\Facades\DB; use Illuminate\Validation\ValidationException;
class ConfirmGoodsReceiptAction {public function __construct(private StockService $stock){} public function handle(GoodsReceipt $receipt):GoodsReceipt{return DB::transaction(function()use($receipt){$receipt=GoodsReceipt::query()->lockForUpdate()->findOrFail($receipt->id);if($receipt->status!=='draft')throw ValidationException::withMessages(['status'=>'Only draft receipts can be confirmed.']);if(StockMovement::where('reference_type',GoodsReceipt::class)->where('reference_id',$receipt->id)->exists())throw ValidationException::withMessages(['status'=>'Receipt inventory is already posted.']);$receipt->load('items.purchaseOrderItem');foreach($receipt->items as $item){$received=(float)$item->purchaseOrderItem->receiptItems()->whereHas('receipt',fn($q)=>$q->where('status','confirmed'))->sum('received_quantity');if($received+(float)$item->received_quantity>(float)$item->ordered_quantity)throw ValidationException::withMessages(['items'=>'Received quantity exceeds remaining PO quantity.']);if(abs(((float)$item->accepted_quantity+(float)$item->rejected_quantity)-(float)$item->received_quantity)>0.001)throw ValidationException::withMessages(['items'=>'Accepted and rejected quantities must equal received quantity.']);}$receipt->update(['status'=>'confirmed']);$this->stock->createPurchaseReceiptMovements($receipt);$po=$receipt->purchaseOrder; $all=$po->items()->get()->every(fn($i)=>(float)$i->receiptItems()->whereHas('receipt',fn($q)=>$q->where('status','confirmed'))->sum('received_quantity')>=(float)$i->quantity);$po->update(['status'=>$all?'fully_received':'partially_received']);return $receipt->fresh('items');});}}
